/**
 * PDF Diagnostic Tool
 * 
 * This is a beginner-friendly tool to help you understand why some PDFs
 * return zero characters when we try to extract text from them.
 * 
 * What this tool does:
 * 1. Checks if the file exists and is a valid PDF
 * 2. Tries to extract text normally (without OCR)
 * 3. Tries to extract text with OCR (for scanned images)
 * 4. Reports what it found
 * 
 * How to use:
 * node pdf-diagnostic.js <path-to-pdf>
 * 
 * Example:
 * node pdf-diagnostic.js ../uploads/documents/myfile.pdf
 * 
 * Generated by CoPilot - 04 Feb 2026
 * 
 * Was having issues with some of the PDFs not returing any texts despite them having text
 * 
 */

import fs from 'fs';
import fetch from 'node-fetch';
import path from 'path';

// The URL where our Tika server is running (Tika extracts text from PDFs)
const TIKA_URL = process.env.TIKA_URL || 'http://localhost:9998/tika';

/**
 * Main function to diagnose a PDF file
 * This function checks why a PDF might not be returning text
 * 
 * @param {string} filePath - The path to the PDF file to check
 */
async function diagnosePDF(filePath) {
  console.log('\n=== PDF DIAGNOSTIC TOOL ===\n');
  
  // STEP 1: Check if the file exists on disk
  if (!fs.existsSync(filePath)) {
    console.error('[ERROR] File not found: ' + filePath);
    console.log('Make sure you provided the correct path to the PDF file.');
    return;
  }

  // STEP 2: Get information about the file (size, modification date, etc.)
  const stats = fs.statSync(filePath);
  console.log('File Name: ' + path.basename(filePath));
  console.log('File Size: ' + stats.size.toLocaleString() + ' bytes');
  console.log('Last Modified: ' + stats.mtime.toLocaleString() + '\n');

  // STEP 3: Read the file into memory as binary data
  const dataBuffer = fs.readFileSync(filePath);
  
  // STEP 4: Check if this is actually a PDF file
  // All valid PDFs start with the characters '%PDF-'
  const pdfHeader = dataBuffer.slice(0, 5).toString();
  if (pdfHeader !== '%PDF-') {
    console.error('[ERROR] This does not appear to be a valid PDF file!');
    console.log('First 5 bytes: ' + pdfHeader);
    console.log('Expected: %PDF-');
    console.log('\nThe file might be corrupted or in the wrong format.');
    return;
  }
  console.log('[OK] Valid PDF header detected\n');

  // STEP 5: Test 1 - Try normal text extraction (without OCR)
  // This works for PDFs with embedded text (like Word documents saved as PDF)
  console.log('TEST 1: Normal text extraction (no OCR)...');
  console.log('This test extracts text that is already embedded in the PDF.');
  console.log('');
  
  try {
    // Send the PDF to Tika server
    const response1 = await fetch(TIKA_URL, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/pdf',  // Tell Tika this is a PDF
        'Accept': 'text/plain'               // We want plain text back
      },
      body: dataBuffer  // Send the PDF file data
    });

    // Check if Tika responded successfully
    if (!response1.ok) {
      console.error('[ERROR] Tika server error: ' + response1.status + ' ' + response1.statusText);
      console.log('Make sure the Tika server is running on port 9998.');
      return;
    }

    // Get the extracted text from Tika's response
    const text1 = await response1.text();
    console.log('Extracted: ' + text1.length + ' characters');
    
    if (text1.length > 0) {
      // Show a preview of what was extracted
      const preview = text1.substring(0, 200).replace(/\n/g, '\\n');
      console.log('First 200 characters: "' + preview + '"');
      console.log('\n[SUCCESS] PDF has embedded text layer');
      console.log('This means the PDF was created digitally (e.g., from Word)');
      console.log('and contains actual text that can be extracted.');
    } else {
      // No text was extracted
      console.log('[WARNING] No text extracted - this might be an image-based PDF');
      console.log('The PDF might be a scanned document or contain only images.');
      console.log('We will try OCR next...');
    }
  } catch (err) {
    console.error('[ERROR] Failed during text extraction: ' + err.message);
    console.log('Check if Tika server is running: http://localhost:9998');
    return;
  }

  // STEP 6: Test 2 - Try OCR text extraction
  // OCR (Optical Character Recognition) reads text from images
  console.log('\nTEST 2: OCR text extraction...');
  console.log('This test uses OCR to read text from images in the PDF.');
  console.log('OCR is like teaching a computer to "read" pictures of text.');
  console.log('');
  
  try {
    // Send the PDF to Tika with OCR enabled
    const response2 = await fetch(TIKA_URL, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/pdf',
        'Accept': 'text/plain',
        'X-Tika-OCRLanguage': 'eng'  // Tell Tika to use English OCR
      },
      body: dataBuffer
    });

    // Check if Tika responded successfully
    if (!response2.ok) {
      console.error('[ERROR] Tika server error: ' + response2.status + ' ' + response2.statusText);
      return;
    }

    // Get the extracted text from Tika's OCR response
    const text2 = await response2.text();
    console.log('Extracted: ' + text2.length + ' characters');
    
    if (text2.length > 0) {
      // Show a preview of what was extracted
      const preview = text2.substring(0, 200).replace(/\n/g, '\\n');
      console.log('First 200 characters: "' + preview + '"');
      console.log('\n[SUCCESS] OCR was able to extract text');
      console.log('The PDF contains images with readable text.');
    } else {
      // OCR also returned nothing
      console.log('[FAILURE] OCR returned no text');
      console.log('\nDIAGNOSIS:');
      console.log('This PDF is likely one of the following:');
      console.log('  * A blank/empty PDF with no content');
      console.log('  * An image with no recognizable text');
      console.log('  * A corrupted file');
      console.log('  * Contains only whitespace or line breaks');
      console.log('\nThings to check:');
      console.log('  1. Is Tesseract OCR installed at: C:\\Program Files\\Tesseract-OCR');
      console.log('  2. Can you open the PDF in a PDF viewer and see text?');
      console.log('  3. Is the file corrupted? Try opening it in Adobe Reader.');
      console.log('  4. If it is a scanned image, is the image quality good enough?');
    }
  } catch (err) {
    console.error('[ERROR] Failed during OCR: ' + err.message);
  }

  console.log('\n=== DIAGNOSTIC COMPLETE ===\n');
}

// MAIN EXECUTION
// Get the PDF file path from the command line arguments
const pdfPath = process.argv[2];

// Check if the user provided a file path
if (!pdfPath) {
  console.error('ERROR: No file path provided!');
  console.error('');
  console.error('Usage: node pdf-diagnostic.js <path-to-pdf>');
  console.error('');
  process.exit(1);// Exit with error code
}

// Run the diagnostic on the provided PDF file
diagnosePDF(pdfPath).catch(err => {
  console.error('Diagnostic failed: ' + err.message);
  console.error('');
  console.error('Full error:');
  console.error(err);// Log the full error object for debugging
  process.exit(1);// Exit with error code
});
